// src/utils/chartConfig.js

export const getChartConfig = (darkMode) => {
  const colors = darkMode ? {
    text: '#D1D4DC',
    grid: '#2A2E39'
  } : {
    text: '#374151',
    grid: '#e5e7eb'
  };

  // Определяем функцию форматирования больших чисел
  const formatLargeNumber = (value) => {
    if (value >= 1000000) {
      return `${(value / 1000000).toFixed(1)}M`;
    } else if (value >= 1000) {
      return `${(value / 1000).toFixed(0)}K`;
    }
    return value;
  };

  // Определяем функцию formatValue как алиас для formatLargeNumber
  const formatValue = formatLargeNumber;

  // Конфигурация для графика платежей (с легендой)
  const paymentChartMargin = { top: 20, right: 20, left: 20, bottom: 60 };

  // Конфигурация для графика остатка (без легенды)
  const balanceChartMargin = { top: 20, right: 20, left: 20, bottom: 60 };

  return {
    // Отступы графиков
    paymentChartMargin,
    balanceChartMargin,
    margin: { top: 20, right: 20, left: 20, bottom: 60 }, // Универсальный отступ с увеличенным нижним отступом

    // Конфигурация оси X
    xAxisConfig: {
      tick: { fill: colors.text },
      stroke: colors.grid,
      height: 45,
      dy: 10,
      label: {
        value: 'Year',
        position: 'insideBottom',
        offset: 40, // Увеличиваем отступ для метки Year
        fill: colors.text
      }
    },

    // Конфигурация оси Y
    yAxisConfig: {
      tick: { fill: colors.text },
      stroke: colors.grid,
      width: 60,
    },

    // Функции форматирования
    formatLargeNumber,
    formatValue,

    // Конфигурация для отображения символа валюты
    getCurrencyLabel: (currencySymbol) => ({
      value: currencySymbol,
      angle: 0,
      position: 'insideLeft',
      offset: -5,
      dy: -15,
      dx: 10,
      fill: colors.text
    }),

    // Конфигурация легенды с фиксированным положением
    legendConfig: {
      verticalAlign: 'bottom',
      align: 'center',
      wrapperStyle: {
        paddingTop: 20,
        marginBottom: 20,
        position: 'relative',
        bottom: 0
      }
    }
  };
};
